const $ = s => document.querySelector(s);
const types = {trigger:['ϟ','Trigger','What starts the work','#a06a1f','#fbf0d8'],agent:['✳','Agent','Who does the work','#487154','#eaf1e8'],prompt:['≡','Prompt','Instructions to follow','#72629a','#f0ecf6'],action:['↗','Action','Something to execute','#497785','#e9f1f3'],artifact:['▤','Artifact','Evidence to learn from','#b2694c','#f9ece6'],human:['◎','Human','Review and decide','#5969a1','#edf0fa']};
const lanes=['Intake','Execute','Verify','Ship','Learn'];
const stages=[['Start with an empty board','Decide what starts the work, who does it, and what “done” means.','Add the basic loop →'],['The smallest useful loop','0–15 min · An issue starts an executor. An agent implements it, reports, and opens a PR for a human.','Add test feedback →'],['Make failure a loop','15–25 min · Test before opening a PR. Send failures back with a bounded retry budget.','Add cleanup →'],['Keep the change simple','25–32 min · Simplify the diff without changing behavior, then test the final result.','Add code review →'],['A second pair of eyes','32–40 min · An independent agent reviews the diff. Findings return to the implementer.','Add mention triggers →'],['Let agents hand off work','40–47 min · A trusted @ship-loop mention resumes the executor on the same branch.','Add artifacts →'],['Capture the unexpected','47–53 min · Record obstacles, attempted fixes, and evidence—even when a run fails.','Add Doctor →'],['Close the learning loop','53–60 min · Doctor reads the evidence and proposes a focused follow-up issue for another pass.','Workshop complete ✓']];
let state={cards:[],edges:[],stage:0},history=[],connecting=false,source=null,pendingEdge=null,dragId=null;
try{const saved=JSON.parse(localStorage.getItem('ship-loop-board-v1'));if(saved&&Array.isArray(saved.cards)&&Array.isArray(saved.edges)&&Number.isInteger(saved.stage)&&saved.stage>=0&&saved.stage<stages.length)state=saved;}catch{}
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const theme=t=>`--color:${types[t][3]};--tint:${types[t][4]}`;
function checkpoint(){history.push(JSON.stringify(state));if(history.length>30)history.shift();}
function save(){try{localStorage.setItem('ship-loop-board-v1',JSON.stringify(state));$('#saved').textContent='Saved on this device';}catch{$('#saved').textContent='Storage unavailable · export to save';}}
function render(){save();$('#library').innerHTML=Object.entries(types).map(([k,v])=>`<button class="library-item" data-type="${k}" style="${theme(k)}"><span class="type-icon">${v[0]}</span><span><strong>${v[1]}</strong><small>${v[2]}</small></span><span class="plus">+</span></button>`).join('');$('#lanes').innerHTML=lanes.map((name,lane)=>`<section class="lane" data-lane="${lane}"><div class="lane-heading">${String(lane+1).padStart(2,'0')} / ${name.toUpperCase()}<small>${state.cards.filter(c=>c.lane===lane).length}</small></div>${state.cards.filter(c=>c.lane===lane).map(c=>`<article class="card ${source===c.id?'selected':''}" tabindex="0" role="button" aria-label="Edit ${escape(c.title)}" draggable="true" data-id="${c.id}" style="${theme(c.type)}"><div class="card-type"><span>${types[c.type][0]} ${types[c.type][1]}</span><span>⠿</span></div><h3>${escape(c.title)}</h3><p>${escape(c.body)}</p><div class="card-bottom"><span>CLICK TO EDIT</span><button data-link="${c.id}" aria-label="Connect ${escape(c.title)}">⊕</button></div></article>`).join('')}<button class="slot" data-add="${lane}">＋ Add a block</button></section>`).join('');
const stage=stages[state.stage];$('#step-number').textContent=`0${state.stage} / 07`;$('#step-title').textContent=stage[0];$('#step-description').textContent=stage[1];$('#next').textContent=stage[2];$('#next').disabled=state.stage===7;$('#progress').innerHTML=stages.slice(1).map((_,i)=>`<div class="progress-segment ${i<state.stage?'active':''}"></div>`).join('');$('#count').textContent=`${state.cards.length} blocks · ${state.edges.length} connections`;$('#undo').disabled=!history.length;$('#connect').textContent=connecting?'Cancel connection':'↗ Connect blocks';$('#connection-hint').classList.toggle('active',connecting);$('#connection-hint').textContent=connecting?(source?'Choose the destination block.':'Choose the starting block.'):'Click a card to edit. Drag cards between lanes. Use Connect blocks to draw an arrow.';$('#board-status').textContent=state.cards.length?'Your board is saved in this browser.':'Start with a block or follow the workshop ↑';requestAnimationFrame(drawEdges);}
function drawEdges(){const board=$('#board'),base=board.getBoundingClientRect();const svg=$('#arrows');svg.setAttribute('viewBox',`0 0 ${board.offsetWidth} ${board.offsetHeight}`);let result='<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#75906c"/></marker><marker id="retry-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#bd775a"/></marker></defs>';state.edges.forEach((edge,i)=>{const a=document.querySelector(`[data-id="${CSS.escape(edge.from)}"]`),b=document.querySelector(`[data-id="${CSS.escape(edge.to)}"]`);if(!a||!b)return;const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();const retry=edge.kind==='retry';let sx=ar.right-base.left,sy=ar.top-base.top+ar.height/2,tx=br.left-base.left,ty=br.top-base.top+br.height/2,path,lx,ly;if(Math.abs(ar.left-br.left)<5 && br.top>ar.top){sx=ar.left-base.left+ar.width/2;sy=ar.bottom-base.top;tx=br.left-base.left+br.width/2;ty=br.top-base.top;path=`M${sx},${sy} L${tx},${ty}`;lx=sx;ly=(sy+ty)/2;}else if(retry||tx<sx-10){sx=ar.left-base.left+ar.width*.65;sy=ar.bottom-base.top;tx=br.left-base.left+br.width*.35;ty=br.bottom-base.top;const y=Math.max(sy,ty)+18+(i%3)*10;path=`M${sx},${sy} C${sx},${y} ${sx},${y} ${sx-15},${y} L${tx+15},${y} Q${tx},${y} ${tx},${ty}`;lx=(sx+tx)/2;ly=y;}else{path=`M${sx},${sy} C${sx+28},${sy} ${tx-28},${ty} ${tx},${ty}`;lx=(sx+tx)/2;ly=(sy+ty)/2;}result+=`<path d="${path}" fill="none" stroke="${retry?'#bd775a':'#75906c'}" stroke-width="1.5" ${retry?'stroke-dasharray="5 4"':''} marker-end="url(#${retry?'retry-arrow':'arrow'})"/>`;if(edge.label){const width=edge.label.length*5.7+12;result+=`<g class="edge-label" data-edge="${edge.id}" role="button" tabindex="0" aria-label="Edit connection ${escape(edge.label)}"><rect x="${lx-width/2}" y="${ly-9}" width="${width}" height="18" rx="4" fill="#fafbf9" stroke="#e3e7df"/><text x="${lx}" y="${ly+3}" text-anchor="middle" fill="${retry?'#a56348':'#647a5b'}" font-size="10">${escape(edge.label)}</text></g>`;}});svg.innerHTML=result;}
function openCard(id,type='prompt',lane=1){const card=state.cards.find(c=>c.id===id);$('#card-id').value=card?.id||'';$('#card-title').value=card?.title||'';$('#card-body').value=card?.body||'';$('#card-type').innerHTML=Object.entries(types).map(([k,v])=>`<option value="${k}">${v[1]}</option>`).join('');$('#card-type').value=card?.type||type;$('#card-lane').innerHTML=lanes.map((l,i)=>`<option value="${i}">${l}</option>`).join('');$('#card-lane').value=card?.lane??lane;$('#delete').hidden=!card;$('#card-connections').innerHTML=card?state.edges.filter(e=>e.from===id||e.to===id).map(e=>`<div class="connection-row"><span>${e.from===id?'→':'←'} ${escape(state.cards.find(c=>c.id===(e.from===id?e.to:e.from))?.title||'')} · ${escape(e.label)}</span><button type="button" data-remove-edge="${e.id}">Remove</button></div>`).join(''):'';$('#editor').showModal();}
function openEdge(edge){pendingEdge={...edge};$('#edge-summary').textContent=`${state.cards.find(c=>c.id===edge.from)?.title} → ${state.cards.find(c=>c.id===edge.to)?.title}`;$('#edge-label').value=edge.label||'';$('#edge-kind').value=edge.kind||'normal';$('#edge-editor').showModal();}
function chooseCard(id){if(!connecting){openCard(id);return;}if(!source){source=id;render();return;}if(source===id)return;if(state.edges.some(e=>e.from===source&&e.to===id)){$('#connection-hint').textContent='These blocks are already connected. Choose another block.';return;}openEdge({id:uid(),from:source,to:id,label:'Next',kind:'normal'});}
document.addEventListener('click',e=>{const close=e.target.closest('.close');if(close){close.closest('dialog').close();return;}const library=e.target.closest('[data-type]');if(library){openCard(null,library.dataset.type,library.dataset.type==='trigger'?0:library.dataset.type==='artifact'?4:1);return;}const add=e.target.closest('[data-add]');if(add){openCard(null,'prompt',+add.dataset.add);return;}const link=e.target.closest('[data-link]');if(link){connecting=true;source=link.dataset.link;render();return;}const edge=e.target.closest('[data-edge]');if(edge){openEdge(state.edges.find(x=>x.id===edge.dataset.edge));return;}const remove=e.target.closest('[data-remove-edge]');if(remove){checkpoint();state.edges=state.edges.filter(x=>x.id!==remove.dataset.removeEdge);render();remove.closest('.connection-row').remove();return;}const card=e.target.closest('.card');if(card)chooseCard(card.dataset.id);});
document.addEventListener('keydown',e=>{if(e.target.matches('.card')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();chooseCard(e.target.dataset.id);}if(e.target.matches('.edge-label')&&e.key==='Enter')openEdge(state.edges.find(x=>x.id===e.target.dataset.edge));if(e.key==='Escape'){connecting=false;source=null;render();}});
$('#card-form').onsubmit=e=>{e.preventDefault();if(!$('#card-title').value.trim())return;checkpoint();const id=$('#card-id').value;const card={id:id||uid(),title:$('#card-title').value.trim(),body:$('#card-body').value,type:$('#card-type').value,lane:+$('#card-lane').value};if(id)state.cards[state.cards.findIndex(c=>c.id===id)]=card;else state.cards.push(card);$('#editor').close();render();};
$('#delete').onclick=()=>{checkpoint();const id=$('#card-id').value;state.cards=state.cards.filter(c=>c.id!==id);state.edges=state.edges.filter(e=>e.from!==id&&e.to!==id);$('#editor').close();render();};
$('#edge-form').onsubmit=e=>{e.preventDefault();checkpoint();const edge={...pendingEdge,label:$('#edge-label').value.trim()||'Next',kind:$('#edge-kind').value};const index=state.edges.findIndex(x=>x.id===edge.id);if(index>=0)state.edges[index]=edge;else state.edges.push(edge);connecting=false;source=null;$('#edge-editor').close();render();};
$('#connect').onclick=()=>{connecting=!connecting;source=null;render();};$('#undo').onclick=()=>{if(history.length){state=JSON.parse(history.pop());connecting=false;source=null;render();}};$('#reset').onclick=()=>$('#reset-dialog').showModal();$('#confirm-reset').onclick=()=>{checkpoint();state={cards:[],edges:[],stage:0};connecting=false;source=null;$('#reset-dialog').close();render();};
document.addEventListener('dragstart',e=>{const c=e.target.closest('.card');if(c){dragId=c.dataset.id;e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move';}});document.addEventListener('dragover',e=>{const l=e.target.closest('.lane');if(l&&dragId){e.preventDefault();l.classList.add('drag-over');}});document.addEventListener('dragleave',e=>e.target.closest('.lane')?.classList.remove('drag-over'));document.addEventListener('drop',e=>{const l=e.target.closest('.lane');if(!l||!dragId)return;e.preventDefault();checkpoint();const index=state.cards.findIndex(c=>c.id===dragId);if(index<0)return;const [card]=state.cards.splice(index,1);card.lane=+l.dataset.lane;const target=e.target.closest('.card');const before=target?state.cards.findIndex(c=>c.id===target.dataset.id):-1;if(before>=0)state.cards.splice(before,0,card);else state.cards.push(card);dragId=null;render();});document.addEventListener('dragend',()=>{dragId=null;document.querySelectorAll('.drag-over').forEach(e=>e.classList.remove('drag-over'));});
function card(id,title,type,lane,body){if(!state.cards.some(c=>c.id===id))state.cards.push({id,title,type,lane,body});}
function edge(from,to,label='Next',kind='normal'){if(state.cards.some(c=>c.id===from)&&state.cards.some(c=>c.id===to)&&!state.edges.some(e=>e.from===from&&e.to===to))state.edges.push({id:uid(),from,to,label,kind});}
function unlink(from,to){state.edges=state.edges.filter(e=>e.from!==from||e.to!==to);}
$('#next').onclick=()=>{if(state.stage>=7)return;checkpoint();state.stage++;switch(state.stage){case 1:card('issue','Issue created','trigger',0,'A person creates an issue with the desired behavior and acceptance criteria. Event: issues.opened.');card('executor','Launch the agent','action',0,'The executor checks out an issue branch, loads the issue, and launches the coding agent. GitHub Actions or a local script owns this sequence.');card('implement','Implement the issue','agent',1,'Implement the task described in the issue. Follow repository instructions. Make the smallest complete change on the issue branch.');card('report','Report completion','prompt',1,'Report what changed, why it solves the issue, and how it was verified. Include any remaining limitations.');card('pr','Open a ready PR','action',3,'After the required checks pass, have the agent create a pull request and mark it ready for review. Include the issue link, change summary, and verification results.');card('human','Review & merge','human',3,'A person reviews the final diff and evidence, requests changes if needed, and merges the pull request. This completes the Ship Loop.');edge('issue','executor','Opened');edge('executor','implement','Prompt');edge('implement','report','Done');edge('report','pr','Complete');edge('pr','human','Ready');break;case 2:card('tests','Run the tests','action',2,'The executor runs the project’s test command and captures exit status and failure output. Only passing checks allow a ready pull request.');card('retry','Send failure feedback','prompt',2,'The tests failed. Read the attached failure report, fix the cause, and try again on the same branch. Maximum 3 attempts; then stop and ask a person for help.');unlink('report','pr');edge('report','tests','Check');edge('tests','pr','Passed');edge('tests','retry','Failed','retry');edge('retry','implement','Try again ≤ 3','retry');break;case 3:card('cleanup','Simplify & clean up','agent',1,'Review your diff. Remove unused code and unnecessary complexity. Keep behavior unchanged and scope limited to the touched files. Report the cleanup and run tests again.');unlink('report','tests');edge('report','cleanup','Simplify');edge('cleanup','tests','Retest');break;case 4:card('review','Review the code','agent',2,'Independently review the final diff against the issue. Report actionable defects with file, line, triggering condition, and priority. If no blocking findings remain, approve this stage.');unlink('tests','pr');edge('tests','review','Passed');edge('review','pr','No blockers');edge('review','implement','Fix findings','retry');break;case 5:card('mention','@ship-loop mentioned','trigger',0,'An authorized person or explicitly trusted reviewer identity mentions @ship-loop in an issue or PR comment. Resume the same issue branch. Deduplicate events and cap retries. Nikolai currently ignores bot comments; trusted agent mentions require extending that rule.');edge('mention','executor','Resume');unlink('review','implement');edge('review','mention','@ship-loop fix','retry');break;case 6:card('artifact','Record run struggles','artifact',4,'Write struggles.json on completion or failure: issue, run ID, stage, attempted fixes, unexpected problems, error evidence, and outcome. Preserve this artifact even if tests never pass.');edge('implement','artifact','Observations');edge('tests','artifact','Test evidence');edge('review','artifact','Findings');break;case 7:card('doctor','Doctor: learn & improve','agent',4,'Read the run artifact. Identify recurring obstacles and their likely causes. Propose one focused improvement backed by evidence, with a verification plan. Do not silently expand the original issue.');card('followup','Approve a follow-up','human',4,'A person approves Doctor’s proposed improvement and creates a focused issue for another pass. Keep the original PR review and merge decision separate.');edge('artifact','doctor','Run ended');edge('doctor','followup','Proposal');edge('followup','issue','New issue','retry');break;}render();};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({format:'ship-loop-v1',...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ship-loop-board.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
new ResizeObserver(drawEdges).observe($('#board'));window.addEventListener('resize',drawEdges);render();

function updateThemeButton() {
  const dark = document.documentElement.dataset.theme === 'dark';
  $('#theme-toggle').textContent = dark ? '☼ Light' : '☾ Dark';
  $('#theme-toggle').setAttribute('aria-label', dark ? 'Switch to light theme' : 'Switch to dark theme');
}
$('#theme-toggle').onclick = () => {
  const theme = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
  document.documentElement.dataset.theme = theme;
  try { localStorage.setItem('ship-loop-theme', theme); } catch {}
  updateThemeButton();
};
updateThemeButton();
